CREATE MATERIALIZED VIEW order_summary AS
SELECT count(*) AS order_count, COALESCE(sum(total), 0.00) AS total_spent
FROM orders;

SELECT * FROM order_summary;

UPDATE orders SET total = total - 5.00 WHERE total >= 50.00;

SELECT * FROM order_summary;

REFRESH MATERIALIZED VIEW order_summary;

SELECT * FROM order_summary;

